examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchPeriodSelector(
        value = period,
        onValueChange = { period = it },
        presets = presets.map { it.second },
        today = today,
        maxDays = {{maxDays}},
    )
    val iso = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.ROOT).apply {
        timeZone = java.util.TimeZone.getTimeZone("UTC")
    }
    MonarchPeriodSelectorDefaults.resolve(period, today)?.let { range ->
        MonarchText(
            text = "Query: " + iso.format(range.startMillis) + " \u2013 " + iso.format(range.endMillis),
            style = MonarchTextStyle.Caption,
        )
    }
}

examples.setupTemplate:
val today = {{today|millis}}
// The web preset values, as Monarch presets.
val presets = listOf(
    {{presets.0}} to MonarchPeriodPreset.Last7Days,
    {{presets.1}} to MonarchPeriodPreset.Last30Days,
    {{presets.2}} to MonarchPeriodPreset.Last90Days,
    {{presets.3}} to MonarchPeriodPreset.ThisMonth,
    {{presets.4}} to MonarchPeriodPreset.LastMonth,
    {{presets.5}} to MonarchPeriodPreset.Custom,
)
var period by remember {
    mutableStateOf(MonarchPeriodValue(presets.first { it.first == {{selected}} }.second))
}

